(function(root){
const next=d=>new Date(Date.parse(d+'T00:00:00Z')+86400000).toISOString().slice(0,10);
const dates=(a,b)=>{const r=[];for(let d=a;d<=b;d=next(d))r.push(d);return r};
function summarize(map,days){let mm=0,wet=0,zero=0,heavy=0,max=0,run=0,longest=0;for(const d of days){const v=map.get(d);mm+=v/10;wet+=v>=10;zero+=v===0;heavy+=v>=200;max=Math.max(max,v/10);run=v<10&&(run===0||map.has(new Date(Date.parse(d+'T00:00:00Z')-86400000).toISOString().slice(0,10)))?run+1:0;longest=Math.max(longest,run)}return {mm,wet,dry:days.length-wet,zero,heavy,max,longest,intensity:wet?mm/wet:null}}
function defaultSelection(cities,current){return [...new Set([current,'oslo','bergen','stavanger'])].filter(id=>cities.some(c=>c.id===id))}
function selectedCities(cities,ids){return [...new Set(ids)].map(id=>cities.find(c=>c.id===id)).filter(Boolean)}
function compare(cities){if(!cities.length)return {end:null,expected:0,days:0,years:[],cities:[]};const maps=cities.map(c=>new Map(c.daily.dailyTenths.filter(([,v])=>Number.isFinite(v)&&v>=0)));const last=cities.map(c=>c.daily.last).sort()[0];const end=last<'2026-12-31'?last:'2026-12-31';const expected=dates('2026-01-01',end);const shared=expected.filter(d=>maps.every(m=>m.has(d)));const years=[];for(let y=1991;y<=2020;y++){const ds=dates(y+'-01-01',y+'-12-31');if(maps.every(m=>ds.every(d=>m.has(d))))years.push(y)}return {end,expected:expected.length,days:shared.length,years,cities:cities.map((c,i)=>{const normal=c.monthly.filter(r=>r.month>='1991-01'&&r.month<='2020-12');const stats=years.map(y=>summarize(maps[i],dates(y+'-01-01',y+'-12-31')));const avg=k=>stats.length?stats.reduce((s,r)=>s+r[k],0)/stats.length:null;return {...c,current:shared.length?summarize(maps[i],shared):{},normal:{mm:normal.length===360?normal.reduce((s,r)=>s+r.mm,0)/30:null,wet:avg('wet'),dry:avg('dry'),zero:avg('zero'),heavy:avg('heavy')}}})}}
const api={compare,defaultSelection,selectedCities};if(typeof module==='object')module.exports=api;else root.CityComparison=api;
})(typeof window==='undefined'?globalThis:window);
